/**
 * The object-storage seam.
 *
 * Reference images have to live somewhere a generation provider can fetch them
 * from. Today that is the local disk; tomorrow it should be S3/R2/GCS without
 * touching a route — same principle as the provider registry, so this
 * interface is deliberately the smallest thing a bucket can satisfy:
 * put / get / remove / sweep.
 *
 * Rules an implementation must honour:
 *  - keys are OPAQUE and generated by us. An implementation must still refuse a
 *    key that does not match `isValidObjectKey` (defence in depth: the read
 *    path takes its key from a URL),
 *  - `get` streams rather than buffering, so serving a 10 MB reference never
 *    costs 10 MB of heap per concurrent request,
 *  - failures come back as values, never exceptions,
 *  - nothing logs object bytes, a client filename, or a secret.
 *
 * Server-only.
 */

/**
 * `<userPrefix>/<random>.<ext>` — a 16-hex per-user directory and an
 * unguessable 32-hex name. The client's filename is never part of a key.
 */
const KEY_PATTERN = /^[a-f0-9]{16}\/[a-f0-9]{32}\.(png|jpg|webp)$/;

export function isValidObjectKey(key: string): boolean {
  return KEY_PATTERN.test(key);
}

export type PutInput = {
  key: string;
  body: Uint8Array;
  /** Sniffed from magic bytes by the caller — never the client's header. */
  contentType: string;
};

export type PutResult = { ok: true } | { ok: false; reason: string };

export type GetResult =
  | {
      ok: true;
      body: ReadableStream<Uint8Array>;
      contentType: string;
      size: number;
      modifiedAt: Date;
    }
  | { ok: false; reason: "not_found" | "invalid_key" | "unavailable" };

export interface ObjectStore {
  /** Opaque driver id, e.g. "local". Matches `STORAGE_DRIVER`. */
  readonly id: string;
  put(input: PutInput): Promise<PutResult>;
  get(key: string): Promise<GetResult>;
  remove(key: string): Promise<void>;
  /**
   * Best-effort deletion of objects last modified before `before`, capped at
   * `limit` deletions so a sweep can never turn into an unbounded job.
   * Returns how many were removed.
   */
  sweep(before: Date, limit: number): Promise<number>;
}
